// Host tests for vroo_wire, against bytes generated by the Dart reference (vectors.h).
#undef NDEBUG // these asserts are the tests, so they stay on in every build type
#include <assert.h>
#include <stdio.h>
#include <string.h>

#include "vectors.h"
#include "vroo_wire.h"

int main(void) {
    // unwrap + header
    const uint8_t *tag, *pkt;
    size_t plen;
    vw_header_t h;
    assert(vw_unwrap(VEC_ENVELOPE, 52, &tag, &pkt, &plen) && plen == 44 && memcmp(tag, VEC_GROUP_TAG, 8) == 0);
    assert(vw_parse_header(pkt, plen, &h) && h.version == 1 && h.type == 3 && h.ttl == 16 && h.src == 0x01020304 &&
           h.session == 0x0A0B0C0D && h.seq == 7);
    assert(!vw_unwrap(VEC_ENVELOPE, 38, &tag, &pkt, &plen));
    uint8_t v2[52];
    memcpy(v2, VEC_ENVELOPE, 52);
    v2[8] = 2; // version 2
    assert(vw_unwrap(v2, 52, &tag, &pkt, &plen) && !vw_parse_header(pkt, plen, &h));

    // dedupe
    static vw_dedupe_t d;
    vw_dedupe_init(&d);
    assert(vw_dedupe_first(&d, 1, 2, 3, 0) && !vw_dedupe_first(&d, 1, 2, 3, 9999));
    assert(vw_dedupe_first(&d, 1, 3, 3, 0));                                                         // new session
    assert(vw_dedupe_first(&d, 1, 2, 3, 10001));                                                     // expired
    assert(vw_dedupe_first(&d, 5, 5, 5, 0xFFFFFF00u) && !vw_dedupe_first(&d, 5, 5, 5, 0x00000100u)); // clock wrap

    // box messages
    vw_box_config_t c;
    assert(vw_decode_box_config(VEC_BOX_CONFIG_FULL, sizeof VEC_BOX_CONFIG_FULL, &c) && c.has_tag && c.has_channel &&
           c.channel == 11 && c.has_password && strcmp(c.password, "abcd-efgh-jkmn-pqrs") == 0);
    assert(vw_decode_box_config(VEC_BOX_CONFIG_TAG_ONLY, sizeof VEC_BOX_CONFIG_TAG_ONLY, &c) && c.has_tag &&
           !c.has_channel && !c.has_password);
    const uint8_t bad_channel[] = {1, 0x10, 0x02, 5};
    assert(!vw_decode_box_config(bad_channel, sizeof bad_channel, &c) && c.has_tag); // c keeps the last good config
    const uint8_t short_password[] = {1, 0x10, 0x04, 3, 'a', 'b', 'c'};
    assert(!vw_decode_box_config(short_password, sizeof short_password, &c));
    const uint8_t control_char[] = {1, 0x10, 0x04, 8, 'a', 'b', 'c', 'd', '\n', 'f', 'g', 'h'};
    assert(!vw_decode_box_config(control_char, sizeof control_char, &c));
    const uint8_t cut_tag[] = {1, 0x10, 0x01, 0x0e, 0x8d};
    assert(!vw_decode_box_config(cut_tag, sizeof cut_tag, &c));
    vw_box_status_t s = {0x00A1B2C3, 1, 3600, false, 2, 100, 90, 3, 1};
    uint8_t out[30];
    assert(vw_encode_box_status(&s, out, 30) == 30 && memcmp(out, VEC_BOX_STATUS, 30) == 0);
    assert(vw_encode_box_status(&s, out, 29) == 0);

    puts("vroo_wire: all tests passed");
    return 0;
}
